import fs from 'node:fs';
import vm from 'node:vm';
import assert from 'node:assert/strict';
import crypto from 'node:crypto';
const base = new URL('./', import.meta.url);
const record = JSON.parse(fs.readFileSync(new URL('attempt2/natural/morning.json', base), 'utf8'));
const source = fs.readFileSync(new URL('../morning-fix/delivery/morning-guard.js', base), 'utf8');
assert.equal(crypto.createHash('sha1').update('blob ' + Buffer.byteLength(source) + '\0' + source).digest('hex'), 'be104666ef64276d2aa9816142b3398dd7f703dc');
function inspect(text) {
  let callback;
  const parent = { SillyTavern: { getContext: () => ({chat: [{is_user: true, mes: record.user}]}) }, Mvu: {events: {COMMAND_PARSED: 'parsed'}} };
  const window = {parent, eventOn: (event, handler) => { if (event === 'parsed') callback = handler; }, eventRemoveListener() {}, addEventListener() {}};
  vm.runInNewContext(source, {window, console});
  const variables = {stat_data: structuredClone(record.before)};
  const commands = structuredClone(record.commands.filter(row => row.phase === 'before' && row.commands.length).at(-1).commands);
  const before = JSON.stringify(variables);
  callback(variables, commands, text);
  assert.equal(JSON.stringify(variables), before, '诊断过程中守卫不得直接写变量');
  return commands.some(command => command.args[0].includes('day6_saiham') && command.args.at(-1) === 'true');
}
assert.equal(inspect(record.text), false, '必须复现原始正文离场命令被过滤');
const voice = '黑暗的梦境中传来低语。你睁开眼睛。希罗解释了活骸化。';
assert.equal(inspect(voice + '黑色运输车辆载着赛哈姆与希罗彻底驶离了中央庭区域。'), false, '必须复现载着与驶离的最小漏判');
assert.equal(inspect(voice + '希罗带着赛哈姆离开了中央庭。'), true, '已有直接带离表述仍能识别');
console.log('已复现实际正文及运输车表述漏判；既有直接离场对照正常。此结果是故障复现，不是修复通过。');
